package com.chickencenter.ui.controllers;import com.chickencenter.model.Employee;import com.chickencenter.service.ExpenseService;import com.chickencenter.util.DropdownUtils;
import com.chickencenter.util.ToastManager;import javafx.collections.FXCollections;import javafx.collections.ObservableList;import javafx.fxml.FXML;import javafx.geometry.Pos;import javafx.scene.control.*;import javafx.scene.layout.HBox;import java.sql.SQLException;public class EmployeesController {    @FXML private TableView<Employee> tblEmployees;    @FXML private TableColumn<Employee, String> colName;    @FXML private TableColumn<Employee, String> colGender;    @FXML private TableColumn<Employee, Boolean> colAction;    @FXML private TextField txtName;    @FXML private ComboBox<String> cmbGender;    @FXML private Button btnSave;    private final ExpenseService expenseService;    private final ObservableList<Employee> employeeList;    private Employee selectedEmployee;    private boolean isEditMode = false;    public EmployeesController() {        this.expenseService = new ExpenseService();        this.employeeList = FXCollections.observableArrayList();    }    @FXML    public void initialize() {        setupTable();        cmbGender.getItems().addAll("Male", "Female", "Other");        cmbGender.setButtonCell(new ListCell<String>() {            protected void updateItem(String item, boolean empty) {                super.updateItem(item, empty);                if (empty || item == null) {                    setText("Select Gender");                } else {                    setText(item);                }            }        });        cmbGender.setPromptText("Select Gender");        DropdownUtils.makeScrollable(cmbGender);        setupAlphabetField(txtName);        loadEmployees();    }        private void setupAlphabetField(TextField field) {        TextFormatter<String> formatter = new TextFormatter<>(change -> {            String newText = change.getControlNewText();            if (newText.isEmpty()) return change;            if (newText.matches("[a-zA-Z ]*")) {                return change;            }            return null;        });        field.setTextFormatter(formatter);    }    private void setupTable() {        tblEmployees.setSelectionModel(null);        tblEmployees.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY);                colName.setCellValueFactory(cellData -> new javafx.beans.property.SimpleStringProperty(cellData.getValue().getName()));        colGender.setCellValueFactory(cellData -> new javafx.beans.property.SimpleStringProperty(cellData.getValue().getGender() != null ? cellData.getValue().getGender() : ""));                colAction.setCellFactory(col -> new TableCell<Employee, Boolean>() {            private final HBox hbox = new HBox();            private final Button btnEdit = new Button("Edit");            {                btnEdit.setStyle("-fx-text-fill: #2563EB; -fx-font-weight: bold; -fx-cursor: hand;");                hbox.setAlignment(Pos.CENTER);                hbox.getChildren().add(btnEdit);                btnEdit.setOnAction(e -> {                    Employee emp = getTableView().getItems().get(getIndex());                    loadEmployeeToForm(emp);                });            }            @Override            protected void updateItem(Boolean item, boolean empty) {                super.updateItem(item, empty);                if (empty) {                    setGraphic(null);                } else {                    setGraphic(hbox);                }            }        });                tblEmployees.setItems(employeeList);    }    private void loadEmployeeToForm(Employee emp) {        selectedEmployee = emp;        isEditMode = true;        txtName.setText(emp.getName());        cmbGender.setValue(emp.getGender());        btnSave.setText("Update");    }    private void loadEmployees() {        try {            employeeList.clear();            employeeList.addAll(expenseService.getAllEmployees());        } catch (SQLException e) {            showError("Error loading employees: " + e.getMessage());        }    }    @FXML    private void saveEmployee() {        btnSave.setDisable(true);                String name = txtName.getText().trim();        String gender = cmbGender.getValue();        if (name.isEmpty()) {            showError("Please enter employee name");            btnSave.setDisable(false);            return;        }        try {            if (isEditMode && selectedEmployee != null) {                selectedEmployee.setName(name);                selectedEmployee.setGender(gender);                expenseService.updateEmployee(selectedEmployee);            } else {                Employee employee = new Employee(name, gender);                expenseService.createEmployee(employee);            }            loadEmployees();            clearFields();            ToastManager.showSuccess("Employee saved successfully!");        } catch (SQLException e) {            showError("Error saving employee: " + e.getMessage());        } finally {            btnSave.setDisable(false);        }    }    @FXML    private void clearFields() {        txtName.clear();                cmbGender.setButtonCell(new ListCell<String>() {            protected void updateItem(String item, boolean empty) {                super.updateItem(item, empty);                if (empty || item == null) {                    setText("Select Gender");                } else {                    setText(item);                }            }        });        cmbGender.getSelectionModel().clearSelection();        cmbGender.setValue(null);        if (cmbGender.getEditor() != null) {            cmbGender.getEditor().clear();        }        cmbGender.setPromptText("Select Gender");                selectedEmployee = null;        isEditMode = false;        btnSave.setText("Save");    }    private void showError(String message) {        Alert alert = new Alert(Alert.AlertType.ERROR);        alert.setTitle("Error");        alert.setHeaderText(null);        alert.setContentText(message);        alert.showAndWait();    }}
